var 
  N: integer;
  IsPrime: boolean;

begin
  writeln('Enter a number: ');
  readln(N);

  IsPrime := True;
  for var i:=2 to round(sqrt(N)) do
    if N mod i = 0 then
    begin
      IsPrime := False;
      break;
    end;

  if IsPrime then
    writeln('Number ',N,' is prime')
  else writeln('Number ',N,' is composite');  
end.

